'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var pkg = require( './../package.json' ).name;
var dgebak = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var JOBS = [
	'permute',
	'scale',
	'both',
	'none'
];
var SIDE = [
	'left',
	'right'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - number of elements along each dimension
* @param {string} job - indicates the operations to be performed
* @param {string} side - indicates the side for scaling (`right` or `left`).
* @returns {Function} benchmark function
*/
function createBenchmark( order, N, job, side ) {
	var scale;
	var sv1;
	var sv2;
	var V;

	scale = uniform( N, -10.0, 10.0, {
		'dtype': 'float64'
	});

	V = uniform( N*N, -10.0, 10.0, {
		'dtype': 'float64'
	});

	if ( isColumnMajor( order ) ) {
		sv1 = 1;
		sv2 = N;
	} else {
		sv1 = N;
		sv2 = 1;
	}

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dgebak( job, side, N, N, 0, N-1, scale, 1, 0, V, sv1, sv2, 0 );
			if ( isnan( z[ i%z.length ] )) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var side;
	var min;
	var max;
	var ord;
	var job;
	var N;
	var f;
	var i;
	var j;
	var k;
	var l;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( i = min; i <= max; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
			for ( j = 0; j < JOBS.length; j++ ) {
				job = JOBS[ j ];
				for ( l = 0; l < SIDE.length; l++ ) {
					side = SIDE[ l ];
					f = createBenchmark( ord, N, job, side );
					bench( pkg+'::square_matrix:order='+ord+',job='+job+',side='+side+',size='+(N*N), f );
				}
			}
		}
	}
}

main();
